search:
{% if posts %}
{% for post in posts.toArray() %}
  {% if (post.indexing == undefined or post.indexing) and post.title != '同人小剧场合集' %}

    {{ post.title }}

    {{ (url + post.path) | uriencode }}
    {% if content %}
      {% if post.password == undefined %}{{ post.content | noControlChars | safe }}{% endif %}
    {% endif %}
    {% if post.categories and post.categories.length>0 %}

        {% for cate in post.categories.toArray() %}
         {{ cate.name }} 
        {% endfor %}

    {% endif %}
    {% if post.tags and post.tags.length>0 %}

          {% for tag in post.tags.toArray() %}
           {{ tag.name }} 
          {% endfor %}

    {% endif %}

  {% endif %}
{% endfor %}
{% endif %}
